class User
{
    private string $name;
    private string $email;

    public function __construct(string $name, string $email)
    {
        $this->name = $name;
        $this->email = $email;
    }
}

// Dengan promotion — compact! ✅
class User
{
    public function __construct(
        private readonly string $name,
        private string $email,
        private int $age = 25,
    ) {}
}
