```php
<?php
try {
    $result = riskyOperation();
} catch (SpecificException $e) {
    // Handle specific error
    log($e->getMessage());
} catch (AnotherException | YetAnotherException $e) {
    // Union catch (PHP 8.0) — handle multiple types
    handleError($e);
} catch (\Throwable $e) {
    // Catch-all — semua exception & error
    reportCritical($e);
} finally {
    // SELALU dijalankan — cocok buat cleanup
    cleanup();
}

// Non-capturing catch (PHP 8.0)
try {
    something();
} catch

