/* 1. Mendaftarkan Kontainer */
.card-container {
    container-type: inline-size;
    container-name: card;
}

/* 2. Mengatur Komponen Berdasarkan Ukuran Kontainer */
@container card (min-width: 400px) {
    .card-content {
        display: flex;
        flex-direction: row;
    }
}
```

